package org.racedaydreams.domain.strength;

import java.util.List;

/** Original movement-specific hinge, unilateral and lower-leg guidance. */
final class LowerBodyTechniqueGuides {
    private LowerBodyTechniqueGuides() {}
    static TechniqueGuide forExercise(String id) {
        return switch(id) {
            case "stiff-leg-deadlift" -> g("hinge","Stand holding a bar at the thighs with knees softly unlocked and trunk braced.","Hinge the hips backwards, keeping the knee angle nearly fixed and bar close; return before your back position changes.","Hamstrings and glutes","Keep knees softly unlocked|Keep the bar close|Use a controlled range","Locking knees forcefully|Rounding to reach lower|Using excessive load","Romanian Deadlift|Hip Thrust");
            case "deficit-deadlift" -> g("hinge","Stand on a low stable riser with the bar on the floor below; grip outside the legs and brace.","Extend hips and knees together to stand with the bar close; lower smoothly and reset on the floor.","Glutes, hamstrings and quadriceps","Start with a small deficit|Check platform stability|Keep the whole foot supported","Using an unstable platform|Adding more depth than you control|Jerking from the floor","Conventional Deadlift|Block Pull");
            case "rack-pull" -> g("hinge","Set equal-height safety pins in a secure rack just below the knees; grip the supported bar and brace.","Extend the hips to stand with the bar close, then return it gently to both pins and reset.","Glutes, back extensors and grip","Check both pins|Keep the bar close|Finish tall without leaning back","Bouncing off the pins|Overloading the shorter range|Leaning backwards at lockout","Conventional Deadlift|Block Pull");
            case "block-pull" -> g("hinge","Support both loaded plate ends on equal stable blocks; stand on the floor between them and brace over the bar.","Stand with the bar close, then lower both plate ends back onto the blocks under control.","Glutes, hamstrings, back extensors and grip","Use equal secure blocks|Keep feet on the floor|Reset each repetition","Uneven or unstable blocks|Bouncing the plates|Jerking with the back","Rack Pull|Conventional Deadlift");
            case "snatch-grip-deadlift" -> g("hinge","Set a wide overhand grip outside the knees on a floor-supported bar; bend hips and knees and brace.","Stand with the bar close while maintaining the wide grip, then lower smoothly and reset.","Posterior chain, upper back and grip","Start lighter than a normal deadlift|Keep the bar close|Use a comfortable wide grip","An excessively wide painful grip|Rounding to reach the bar|Jerking off the floor","Conventional Deadlift|Romanian Deadlift");
            case "cable-pull-through" -> g("hinge","Face away from a low pulley with the rope passing between your legs; stand balanced and brace.","Hinge hips backwards, then extend them to stand while hands hold the rope below the pelvis.","Glutes and hamstrings","Move from the hips|Keep ribs controlled|Keep the rope clear of the body","Squatting instead of hinging|Leaning back at the finish|Pulling mainly with the arms","Romanian Deadlift|Hip Thrust");
            case "barbell-glute-bridge" -> g("bridge","Lie with upper back and head on a mat, knees bent and feet flat; secure a padded bar across the hips.","Lift hips into a controlled shoulder-to-knee line, then lower smoothly while keeping the bar steady.","Glutes and hamstrings","Keep the bar padded and secure|Keep feet planted|Finish without arching the lower back","Rolling the bar towards the abdomen|Overarching at the top|Pushing through the neck","Glute Bridge|Hip Thrust");
            case "lateral-lunge" -> g("split","Stand with space to the side, holding manageable dumbbells beside the body.","Step sideways and sit hips back over the bending leg while the other stays long; push through the working foot to return.","Quadriceps, glutes and inner thighs","Keep the working foot flat|Let knee follow toes|Use a comfortable width","Collapsing the knee inward|Stepping beyond control|Rushing the return","Cossack Squat|Reverse Lunge");
            case "curtsy-lunge" -> g("split","Stand balanced with light dumbbells at your sides and room behind you.","Step one foot gently diagonally behind, lower through a comfortable range and return; keep the front knee comfortable.","Glutes and quadriceps","Use a small diagonal step|Keep the front foot planted|Choose a reverse lunge if uncomfortable","Crossing too far behind|Twisting the front knee|Rushing the descent","Reverse Lunge|Split Squat");
            case "deficit-reverse-lunge" -> g("split","Stand on a low stable platform with manageable dumbbells at your sides.","Step one foot backwards onto the floor below, lower both knees under control and return to the platform.","Quadriceps and glutes","Keep the front foot supported|Start with a low platform|Control the extra range","An unstable platform|Dropping onto the rear leg|Choosing excessive depth","Reverse Lunge|Step-Up");
            case "front-foot-elevated-split-squat" -> g("split","Take a split stance with the front foot on a low stable block and rear forefoot on the floor.","Lower both knees while keeping the front foot flat on the block, then stand through the front leg; change sides.","Quadriceps and glutes","Check the front block|Keep the stance wide enough for balance|Use a controlled range","Raising the rear foot instead|Rocking the block|Pushing mostly from the back foot","Split Squat|Reverse Lunge");
            case "cossack-squat" -> g("squat","Stand in a wide comfortable stance without added load, arms free for balance.","Shift hips towards one side into a controlled side squat while the other leg stays long; return and alternate.","Quadriceps, glutes and inner thighs","Keep the working heel down|Use a comfortable depth|Use support if needed","Forcing hip or ankle range|Collapsing the knee|Dropping quickly into the bottom","Lateral Lunge|Goblet Squat");
            case "pistol-squat" -> g("squat","Hold a stable support and balance on one leg with the other reaching forwards.","Bend the working hip and knee through a controllable range, keeping the free foot clear; use support to return.","Quadriceps and glutes","Use secure assistance|Keep the working foot supported|Choose a shallower range if needed","Forcing full depth|Falling onto the heel|Letting go before balanced","Step-Up|Split Squat");
            case "tibialis-raise" -> g("calf","Lean your back against a wall with feet a comfortable distance forwards and heels on the floor.","Lift toes and forefeet towards the shins while heels remain down, then lower slowly.","Front lower-leg muscles","Keep heels down|Use a comfortable ankle range|Move slowly","Lifting the heels|Rocking the whole body|Forcing ankle discomfort","Bodyweight Calf Raise|Ankle Rocks");
            case "swiss-ball-leg-curl" -> g("curl","Lie on a mat with shoulders supported and heels on a stable exercise ball; lift hips into a controlled line.","Bend knees to draw the ball towards the hips, then roll it away slowly without losing pelvic control.","Hamstrings and glutes","Keep the ball steady|Keep hips controlled|Start with a short range","Dropping the hips abruptly|Losing heel contact|Rushing the return","Sliding Leg Curl|Lying Leg Curl");
            case "sliding-leg-curl" -> g("curl","Lie on a mat with heels on suitable sliders over a smooth clear floor; raise hips with legs nearly straight.","Draw heels towards the hips by bending the knees, then slide out slowly through a controllable range.","Hamstrings and glutes","Check the sliding surface|Keep hips controlled|Use a shorter range if needed","An unsuitable rough surface|Losing pelvic control|Sliding out beyond control","Swiss-Ball Leg Curl|Seated Leg Curl");
            case "forward-lunge", "barbell-lunge", "lunge" -> g("split","Support a manageable bar across the upper back; stand balanced with space to step forwards.","Step forwards and lower both knees under control, then push through the front foot to return; alternate as prescribed.","Quadriceps and glutes","Keep the front foot flat|Keep a stable stance width|Start light while learning balance","Stepping on a tightrope|Knee collapsing inwards|Rushing the return","Dumbbell Lunge|Reverse Lunge");
            case "dumbbell-lunge" -> g("split","Stand tall holding manageable dumbbells beside the body; leave space behind you for the illustrated reverse variation.","Step one foot backwards, lower both knees under control and return through the front leg; change sides.","Quadriceps and glutes","Keep the front foot flat|Keep weights steady|Use a stable stance width","Swinging the weights|Pushing mainly from the back leg|Rushing the return","Reverse Lunge|Split Squat");
            case "high-step-up" -> g("split","Set a stable box no higher than you can control; support a light bar across the upper back and place one whole foot on the box.","Stand through the raised leg, then step down slowly; use a lower box or dumbbells if balance limits control.","Quadriceps and glutes","Check box stability|Keep the whole foot supported|Control the step down","Choosing excessive height|Jumping from the floor|Dropping back down","Step-Up|Split Squat");
            case "standing-leg-curl" -> g("curl","Adjust the standing curl machine with working knee near its pivot and roller behind the lower calf; hold the support handles.","Bend the working knee to lift the heel behind, then lower slowly while keeping the thigh steady; change sides.","Hamstrings","Adjust roller position|Keep hips supported|Control the return","Swinging the thigh|Arching the back|Letting the weight slam","Seated Leg Curl|Lying Leg Curl");
            case "nordic-hamstring-curl" -> g("curl","Kneel on padding with ankles securely held by suitable padded equipment; place a raised hand support in front.","Keep hips and trunk aligned as you lean forwards from the knees through a small controlled range; catch with hands and use assistance to return.","Hamstrings","Check ankle support|Start with a short assisted range|Keep hands ready","Unsecured ankles|Folding at the hips|Dropping beyond control","Seated Leg Curl|Sliding Leg Curl");
            case "glute-ham-raise" -> g("curl","Adjust a glute-ham developer so ankles are secure and thighs and knees supported on its rounded pad.","From a controlled extended body position, bend the knees to raise the torso, then lower slowly; use assistance if needed.","Hamstrings and glutes","Check machine adjustment|Keep hips controlled|Use a manageable range","Unsecured ankles|Bending mainly through the back|Dropping towards the floor","Nordic Hamstring Curl|Lying Leg Curl");
            case "leg-press-calf-raise" -> g("calf","Sit supported in the leg press with forefeet securely on the platform edge, heels free and knees softly straight; set safeties.","Raise the heels by pressing through the forefeet, then lower slowly through a comfortable ankle range.","Calves","Keep forefeet secure|Keep knee angle steady|Control the ankle movement","Feet slipping off the platform|Locking knees forcefully|Bouncing through the heels","Standing Calf Raise|Seated Calf Raise");
            case "single-leg-calf-raise" -> g("calf","Use a standing calf machine with pads secure, hands on handles and one forefoot on the platform; keep the other foot clear.","Raise the working heel, pause briefly and lower slowly; use less load than for two legs and change sides.","Calves","Keep balance support|Use a manageable single-leg load|Keep the knee steady","Bouncing|Rolling the ankle outward|Losing secure foot contact","Standing Calf Raise|Bodyweight Single-Leg Calf Raise");
            case "donkey-calf-raise" -> g("calf","Adjust a donkey calf machine with resistance supported across the hips, forearms supported and forefeet on its platform.","Keep knees softly straight and raise the heels, then lower slowly while maintaining trunk support.","Calves","Check hip-pad position|Keep the trunk supported|Control both directions","Loading the lower back incorrectly|Bouncing the heels|Losing platform contact","Standing Calf Raise|Seated Calf Raise");
            default -> EquipmentTechniqueGuides.forExercise(id);
        };
    }
    private static TechniqueGuide g(String pattern,String setup,String movement,String muscles,String cues,String mistakes,String alternatives) {
        return new TechniqueGuide(pattern,setup,movement,List.of(cues.split("\\|")),List.of(mistakes.split("\\|")),muscles,List.of(alternatives.split("\\|")));
    }
}
